import re    # Importing regular expressions module. It provides a way of working with patterns and strings, called regexs/patterns or 'regex'. Python's built-in Module that supports processing text data using Pattern Matchings (also known as Regex). 
def match_string(s):     # Defining function named "match string" which takes one parameter s ie input String  
    return bool(re.search('^a.*bbb$', s))      # '.' in regex means to find any character (including none) between them, not just exact three occurances of b's  so this will work correctly if you want allow for all characters including newline and backspace etc.,

